#include <Cellerator/compiler/backend/nvcc/implement_host_device_split_compilation_v1.hh>
namespace cellerator::compiler::backend::nvcc::v1 {
std::optional<compilation_graph> make_compilation_graph(const split_request&r,split_status*s) noexcept{auto set=[&](auto v){if(s)*s=v;};if(!r.semantic_identity){set(split_status::invalid_identity);return{};}if(r.generated_cuda.empty()||r.output.empty()){set(split_status::invalid_path);return{};}compilation_graph g{r.semantic_identity,{}};auto map=std::vector<source_map_entry>{{r.generated_cuda,"semantic.cell",1,1}};if(r.route==compilation_route::whole_cuda)g.jobs.push_back({job_kind::device_compile,r.generated_cuda,r.output,r.architectures,{},map,true,false});else if(r.route==compilation_route::split_host_device){if(r.generated_host.empty()){set(split_status::invalid_path);return{};}g.jobs.push_back({job_kind::device_compile,r.generated_cuda,r.output+".device.o",r.architectures,{},map,true,false});g.jobs.push_back({job_kind::host_compile,r.generated_host,r.output+".host.o",{}, {},{{r.generated_host,"semantic.cell",1,1}},true,false});g.jobs.push_back({job_kind::device_link,r.output+".device.o",r.output,r.architectures,{},{{r.output+".device.o","semantic.cell",1,1}},true,false});}else{set(split_status::invalid_route);return{};}for(const auto&j:g.jobs)if(validate_job(j)!=contract_status::ok){set(split_status::invalid_job);return{};}set(split_status::ok);return g;}
}
